INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('40000000-0000-4000-8000-000000001000','1','cloze','{"type":"cloze","schemaVersion":1,"id":"40000000-0000-4000-8000-000000001000","revision":1,"targetId":"40000000-0000-4000-8000-000000000000","prompt":"Der Antrag ___ von der Behörde geprüft. (werden, Präsens)","instruction":{"en":"Complete only the gap, using the expression or form specified in parentheses.","de":"Ergänze nur die Lücke mit dem Ausdruck oder der Form in Klammern."},"hint":{"en":"Use werden plus the past participle.","de":"Verwende werden und das Partizip II."},"slots":[{"id":"form","label":"Form"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"cloze","values":[{"slotId":"form","text":"wird"}]}],"explanation":{"en":"The present passive uses a present form of werden and the past participle: wird geprüft / wird bearbeitet.","de":"Das Vorgangspassiv im Präsens besteht aus werden und dem Partizip II: wird geprüft / wird bearbeitet."}}','de-nfc-trim-v1','Original Codex-authored controlled examples, 7 October 2026; AI editorial assistance, not independent German review. No legacy sentences imported.','pending');
