INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('40000000-0000-4000-8000-000000001020','1','cloze','{"type":"cloze","schemaVersion":1,"id":"40000000-0000-4000-8000-000000001020","revision":1,"targetId":"40000000-0000-4000-8000-000000000010","prompt":"Der Zug hatte Verspätung, sodass ich zu spät ___. (ankommen, Präteritum)","instruction":{"en":"Complete only the gap, using the expression or form specified in parentheses.","de":"Ergänze nur die Lücke mit dem Ausdruck oder der Form in Klammern."},"hint":{"en":"Sodass introduces the consequence in a subordinate clause.","de":"Sodass leitet die Folge in einem Nebensatz ein."},"slots":[{"id":"form","label":"Form"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"cloze","values":[{"slotId":"form","text":"ankam"}]}],"explanation":{"en":"A sodass clause places the conjugated verb at the end.","de":"Im Nebensatz mit sodass steht das konjugierte Verb am Ende."}}','de-nfc-trim-v1','Original Codex-authored controlled examples, 7 October 2026; AI editorial assistance, not independent German review. No legacy sentences imported.','pending');
