INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('40000000-0000-4000-8000-000000001022','1','cloze','{"type":"cloze","schemaVersion":1,"id":"40000000-0000-4000-8000-000000001022","revision":1,"targetId":"40000000-0000-4000-8000-000000000011","prompt":"Ich besuche einen Kurs, um meine Aussprache ___ verbessern. (Infinitivpartikel)","instruction":{"en":"Complete only the gap, using the expression or form specified in parentheses.","de":"Ergänze nur die Lücke mit dem Ausdruck oder der Form in Klammern."},"hint":{"en":"Use zu before the infinitive.","de":"Vor dem Infinitiv steht zu."},"slots":[{"id":"form","label":"Form"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"cloze","values":[{"slotId":"form","text":"zu"}]}],"explanation":{"en":"Um … zu expresses purpose when both clauses have the same subject.","de":"Um … zu beschreibt eine Absicht, wenn beide Satzteile dasselbe Subjekt haben."}}','de-nfc-trim-v1','Original Codex-authored controlled examples, 7 October 2026; AI editorial assistance, not independent German review. No legacy sentences imported.','pending');
