INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('40000000-0000-4000-8000-000000001024','1','cloze','{"type":"cloze","schemaVersion":1,"id":"40000000-0000-4000-8000-000000001024","revision":1,"targetId":"40000000-0000-4000-8000-000000000012","prompt":"Ich habe vor, mich auf das Gespräch ___. (vorbereiten, Infinitiv mit zu)","instruction":{"en":"Complete only the gap, using the expression or form specified in parentheses.","de":"Ergänze nur die Lücke mit dem Ausdruck oder der Form in Klammern."},"hint":{"en":"Put zu between the prefix and the verb stem.","de":"Setze zu zwischen Vorsilbe und Verbstamm."},"slots":[{"id":"form","label":"Form"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"cloze","values":[{"slotId":"form","text":"vorzubereiten"}]}],"explanation":{"en":"With separable verbs, zu is inserted: vorbereiten → vorzubereiten; teilnehmen → teilzunehmen.","de":"Bei trennbaren Verben steht zu im Wort: vorbereiten → vorzubereiten; teilnehmen → teilzunehmen."}}','de-nfc-trim-v1','Original Codex-authored controlled examples, 7 October 2026; AI editorial assistance, not independent German review. No legacy sentences imported.','pending');
