INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('40000000-0000-4000-8000-000000001026','1','cloze','{"type":"cloze","schemaVersion":1,"id":"40000000-0000-4000-8000-000000001026","revision":1,"targetId":"40000000-0000-4000-8000-000000000013","prompt":"Der Vertrag, ___ ich gestern unterschrieben habe, gilt ab Mai. (Relativpronomen)","instruction":{"en":"Complete only the gap, using the expression or form specified in parentheses.","de":"Ergänze nur die Lücke mit dem Ausdruck oder der Form in Klammern."},"hint":{"en":"The relative pronoun is the object of the relative clause.","de":"Das Relativpronomen ist das Objekt im Relativsatz."},"slots":[{"id":"form","label":"Form"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"cloze","values":[{"slotId":"form","text":"den"}]}],"explanation":{"en":"For a masculine accusative antecedent use den; for a neuter one use das.","de":"Im Akkusativ steht bei einem maskulinen Bezugswort den, bei einem neutralen das."}}','de-nfc-trim-v1','Original Codex-authored controlled examples, 7 October 2026; AI editorial assistance, not independent German review. No legacy sentences imported.','pending');
